import type { Metadata } from "next"; import { notFound } from "next/navigation"; import Link from "next/link"; import { calculateBMI } from "@/lib/bmi"; import { ArticlePage } from "@/components/article-page"; export const dynamicParams=true; type Props={params:Promise<{height:string;weight:string}>}; export async function generateMetadata({params}:Props):Promise<Metadata>{const {height,weight}=await params;const h=Number(height),w=Number(weight);const r=calculateBMI(h,w);return {title:r?`BMI for ${h} cm and ${w} kg: ${r.bmi}`:"BMI calculation",description:r?`A ${h} cm person weighing ${w} kg has a BMI of ${r.bmi}, in the ${r.category} category.`:"BMI calculation"}} export default async function Page({params}:Props){const {height,weight}=await params;const h=Number(height),w=Number(weight),r=calculateBMI(h,w);if(!r)notFound();return <ArticlePage path={`/bmi/${h}-cm-${w}-kg`} title={`BMI for ${h} cm and ${w} kg`} description={`At ${h} cm and ${w} kg, the calculated adult BMI is ${r.bmi}.`}><h2>Result: BMI {r.bmi} ({r.category})</h2><p>This result is based on the standard formula: {w} kg divided by {h/100} m squared. The healthy-weight BMI range for this height is approximately {r.healthyMin} to {r.healthyMax} kg.</p><h2>What this means</h2><p>{r.advice}</p><p><Link className="text-teal-700 underline" href="/bmi-calculator">Calculate a different height and weight</Link> or read our complete BMI guide for limits and practical next steps.</p></ArticlePage>}
