export type Category = "Underweight"|"Healthy weight"|"Overweight"|"Obesity";
export type BMIResult = { bmi:number; category:Category; risk:string; healthyMin:number; healthyMax:number; ideal:number; difference:number; advice:string };
export function calculateBMI(heightCm:number, weightKg:number): BMIResult | null { if(!Number.isFinite(heightCm)||!Number.isFinite(weightKg)||heightCm<80||heightCm>250||weightKg<20||weightKg>500)return null; const bmi=weightKg/((heightCm/100)**2); const healthyMin=18.5*(heightCm/100)**2,healthyMax=24.9*(heightCm/100)**2,ideal=(healthyMin+healthyMax)/2; let category:Category="Healthy weight",risk="Generally lowest health risk",advice="Your measurement falls in the usual healthy BMI range. Keep supporting it with regular movement, nourishing meals, sleep, and routine care."; if(bmi<18.5){category="Underweight";risk="May warrant review";advice="A BMI below the usual adult range can have many causes. If this is unintentional or accompanied by symptoms, speak with a clinician or dietitian."} else if(bmi<25){} else if(bmi<30){category="Overweight";risk="Potentially increased risk";advice="A modest, sustainable change in weight or waist circumference can improve health markers for many people. Focus on habits, not rapid loss."} else {category="Obesity";risk="Increased risk";advice="BMI in this range is associated with higher risk of some conditions, but it is not a diagnosis. A clinician can help put it in context and discuss supportive options."} return {bmi:+bmi.toFixed(1),category,risk,healthyMin:+healthyMin.toFixed(1),healthyMax:+healthyMax.toFixed(1),ideal:+ideal.toFixed(1),difference:+(weightKg-ideal).toFixed(1),advice}; }
export function bmiFromImperial(feet:number,inches:number,pounds:number){return {heightCm:(feet*12+inches)*2.54,weightKg:pounds*0.45359237}}
